              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {mockAccounts.map((account) => (
                  <AccountSummaryCard
                    key={account.accountNumber}
                    {...account}
                    onClick={() => console.log(`View details for ${account.name}`)}
                  />
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

